-- Duties import. GENERATED FILE: contains real staff names. Keep it outside the repository. Not applied by anything automatic.
-- Review the counts below, then run once in the SQL editor with the owner's yes. Safe to run twice (everything is "on conflict do nothing").
create temp table _duty_cand on commit drop as select s.id sid, p.id pid from public.duty_staff s join public.profiles p on p.active and p.role <> 'customer'
      and (lower(s.roster_name) = any (regexp_split_to_array(lower(p.full_name), '[^a-z0-9]+')) or regexp_replace(lower(p.full_name), '[^a-z0-9]', '', 'g') = regexp_replace(lower(s.roster_name), '[^a-z0-9]', '', 'g')) where s.profile_id is null;
delete from _duty_cand where sid in (select sid from _duty_cand group by sid having count(*) > 1) or pid in (select pid from _duty_cand group by pid having count(*) > 1) or pid in (select profile_id from public.duty_staff where profile_id is not null);
update public.duty_staff s set profile_id = c.pid from _duty_cand c where s.id = c.sid;
